# Projections ----
## Setup ----
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

# Age data only, as in the projection vignette.
base_data <- FIMS::data_big |>
  dplyr::filter(!type %in% c("age_to_length_conversion", "length_comp"))
n_projection_years <- 5
terminal_year <- max(base_data[["timing"]][base_data[["type"]] == "catch"])
terminal_catch <- base_data |>
  dplyr::filter(type == "catch", fleet == "fleet1", timing == terminal_year) |>
  dplyr::pull(observed)

# The data with 5 projection years of fleet1 catch, -999 when missing, and
# weight at age for the start of each projection year. FIMSFrame() fills the
# other data types with missing values.
projection_data <- function(projected_catch) {
  catch_rows <- base_data |>
    dplyr::filter(type == "catch", fleet == "fleet1", timing == terminal_year)
  weight_rows <- base_data |>
    dplyr::filter(type == "weight_at_age", timing == terminal_year + 1)
  base_data |>
    dplyr::bind_rows(
      catch_rows[rep(1, n_projection_years), ] |>
        dplyr::mutate(
          timing = terminal_year + seq_len(n_projection_years),
          observed = projected_catch
        ),
      weight_rows[rep(seq_len(nrow(weight_rows)), n_projection_years), ] |>
        dplyr::mutate(
          timing = rep(
            terminal_year + 1 + seq_len(n_projection_years),
            each = nrow(weight_rows)
          )
        )
    ) |>
    FIMSFrame()
}

# Fits the default model. fleet1's log_Fmort in the projection years has
# `projected_f_type` as its estimation type. The projection years'
# recruitment deviations stay random effects: with no data they integrate out
# of the likelihood, so they cannot change the hindcast. Fixing them at 0
# would keep them in the recruitment process density and lower `log_sd`.
fit_projection <- function(data, projected_f_type) {
  parameters <- setup_default_parameters(data)
  is_projected_f <- parameters[["label"]] %in% "log_Fmort" &
    parameters[["fleet"]] %in% "fleet1" &
    parameters[["timing"]] %in% (terminal_year + seq_len(n_projection_years))
  parameters[["estimation_type"]][is_projected_f] <- projected_f_type
  parameters |>
    initialize_fims(data = data) |>
    fit_fims()
}

# Each fixed effect of the model without projections, joined to the same
# parameter in a model with projections.
compare_hindcast <- function(projection_fit) {
  no_projection_estimates <- get_estimates(no_projection_fit) |>
    dplyr::filter(estimation_type == "fixed_effects") |>
    dplyr::select(
      module_name, fleet, label, year_i, age,
      base_estimate = estimated, base_uncertainty = uncertainty
    )
  projection_estimates <- get_estimates(projection_fit) |>
    dplyr::select(module_name, fleet, label, year_i, age, estimated, uncertainty)
  no_projection_estimates |>
    dplyr::left_join(
      projection_estimates,
      by = c("module_name", "fleet", "label", "year_i", "age")
    ) |>
    dplyr::mutate(
      difference_in_standard_errors =
        abs(estimated - base_estimate) / base_uncertainty,
      relative_difference = abs(estimated - base_estimate) / abs(base_estimate),
      relative_uncertainty_difference =
        abs(uncertainty - base_uncertainty) / base_uncertainty
    )
}

no_projection_fit <- fit_projection(FIMSFrame(base_data), "constant")

## IO correctness ----
test_that("projection years with no data do not change the hindcast estimates", {
  hindcast <- fit_projection(
    projection_data(rep(-999, n_projection_years)),
    projected_f_type = "constant"
  ) |>
    compare_hindcast()
  #' @description Test that every fixed effect of the model without projections is in the model with 5 projection years.
  expect_false(anyNA(hindcast[["estimated"]]))
  #' @description Test that projection years with no data and a constant F change no hindcast estimate by more than 0.01 standard errors.
  expect_lt(max(hindcast[["difference_in_standard_errors"]]), 0.01)
  #' @description Test that projection years with no data and a constant F change no hindcast standard error by more than 1%.
  expect_lt(max(hindcast[["relative_uncertainty_difference"]]), 0.01)
})

test_that("a low projected catch changes the hindcast estimates by less than 10%", {
  hindcast <- fit_projection(
    projection_data(rep(terminal_catch * 0.5, n_projection_years)),
    projected_f_type = "fixed_effects"
  ) |>
    compare_hindcast()
  #' @description Test that a projected catch of half the terminal catch, with F estimated, changes each hindcast estimate by less than 10%.
  expect_lt(max(hindcast[["relative_difference"]]), 0.1)
  #' @description Test that a projected catch of half the terminal catch, with F estimated, changes each hindcast standard error by less than 10%.
  expect_lt(max(hindcast[["relative_uncertainty_difference"]]), 0.1)
})

## Edge handling ----
test_that("a projected catch the stock cannot support changes the hindcast estimates", {
  # The model has to make the high catches possible, which pulls the hindcast
  # away from the fit without projections. The last projected F is poorly
  # informed, so fit_fims() warns about its standard error.
  hindcast <- suppressWarnings(fit_projection(
    projection_data(rep(terminal_catch * 2, n_projection_years)),
    projected_f_type = "fixed_effects"
  )) |>
    compare_hindcast()
  #' @description Test that a projected catch of twice the terminal catch, with F estimated, changes at least 1 hindcast estimate by more than 10%.
  expect_gt(max(hindcast[["relative_difference"]]), 0.1)
  #' @description Test that a projected catch of twice the terminal catch, with F estimated, changes at least 1 hindcast standard error by more than 10%.
  expect_gt(max(hindcast[["relative_uncertainty_difference"]]), 0.1)
})

## Error handling ----
# No built-in errors to test.
